<?php
namespace App\Domain\BulkImport\Services;
use App\Domain\BulkImport\Enums\{MigrationBatchStatus,MigrationItemStatus};use App\Models\{MigrationBatch,MigrationBatchItem};use Illuminate\Http\UploadedFile;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use RuntimeException;
class CsvMigrationParser{private array $required=['external_row_id','document_type_code','district_code','revenue_circle_code','title'];public function createBatch(UploadedFile $file,int $userId,string $template='ASSAM-LR-MIGRATION-v1'):MigrationBatch{$path=$file->getRealPath();$sha=hash_file('sha256',$path);$batch=MigrationBatch::create(['ulid'=>(string)Str::ulid(),'batch_reference'=>'MIG-'.now()->format('Ymd').'-'.Str::upper(Str::random(6)),'template_version'=>$template,'original_manifest_name'=>basename($file->getClientOriginalName()),'manifest_sha256'=>$sha,'status'=>MigrationBatchStatus::Parsing,'created_by'=>$userId]);$h=fopen($path,'rb');$header=fgetcsv($h);if(!$header)throw new RuntimeException('CSV header is missing.');$header=array_map(fn($v)=>Str::snake(trim((string)$v)),$header);foreach($this->required as $column)if(!in_array($column,$header,true))throw new RuntimeException('Required column missing: '.$column);$rowNo=1;$count=0;DB::beginTransaction();try{while(($row=fgetcsv($h))!==false){$rowNo++;if(count($row)!==count($header)){MigrationBatchItem::create(['migration_batch_id'=>$batch->id,'external_row_id'=>'ROW-'.$rowNo,'source_row_number'=>$rowNo,'source_payload'=>['raw'=>$row],'status'=>MigrationItemStatus::Invalid,'errors'=>['COLUMN_COUNT_MISMATCH']]);$count++;continue;}$payload=array_combine($header,$row);$external=trim((string)($payload['external_row_id']??''));if($external==='')$external='ROW-'.$rowNo;MigrationBatchItem::create(['migration_batch_id'=>$batch->id,'external_row_id'=>$external,'source_row_number'=>$rowNo,'source_payload'=>$payload,'status'=>MigrationItemStatus::Pending]);$count++;if($count%1000===0){DB::commit();DB::beginTransaction();}}DB::commit();}catch(\Throwable $e){DB::rollBack();throw $e;}finally{fclose($h);}$batch->update(['total_items'=>$count,'status'=>MigrationBatchStatus::Uploaded]);return $batch;}}
